      margin: 0 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
    }

    form {
      display: grid;
      gap: 1.5rem;
    }

    .form-field {
      padding: 1rem;
      background: var(--panel-strong);
      border: 0.0625rem solid var(--border);
      border-radius: 1rem;
    }

    fieldset {
      margin: 0;
      padding: 0;
      border: 0;
