      display: flex;
      align-items: center;
      gap: 0.75rem;
      min-width: 0;
      padding: 0.9rem 1rem;
      color: var(--text);
      background: #0b1020;
      border: 0.0625rem solid var(--border);
      border-radius: 0.875rem;
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
