      background: #251f47;
      border-color: var(--accent-strong);
    }

    .radio-option:has(input:focus-visible) {
      outline: 0.1875rem solid var(--focus);
      outline-offset: 0.1875rem;
    }

    input[type="radio"] {
      width: 1.25rem;
      height: 1.25rem;
      margin: 0;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    .option-text {
      min-width: 0;
      font-weight: 700;
      overflow-wrap: anywhere;
    }

    .error-message,
    .status-message {
      margin: 0;
