      min-height: 1.5rem;
      color: var(--error);
      font-weight: 700;
    }

    .status-message {
      color: var(--success);
      font-weight: 700;
    }

    button {
      width: 100%;
      padding: 0.95rem 1.25rem;
      color: #080b12;
      background: linear-gradient(135deg, #c4b5fd 0%, #facc15 100%);
      border: 0;
      border-radius: 999rem;
      font: inherit;
      font-weight: 900;
      cursor: pointer;
      box-shadow: 0 1rem 2rem #00000066;
    }

    button:hover {
      filter: brightness(1.05);
    }

    button:focus-visible {
      outline: 0.1875rem solid var(--focus);
      outline-offset: 0.25rem;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      body,
      .card,
      .form-field,
      .radio-option {
        background: Canvas;
        color: CanvasText;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .eyebrow,
      .intro,
      .required-note,
      .error-message,
      .status-message {
        color: CanvasText;
      }

      button {
        color: ButtonText;
        background: ButtonFace;
        border: 0.125rem solid ButtonBorder;
      }

      .skip-link,
      button:focus-visible,
      .radio-option:has(input:focus-visible) {
        outline-color: Highlight;
