<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification style</h1>
      <p class="intro">Select the channel that works best for timely updates.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-error">
            <legend>
              How do you prefer to receive notifications?
              <span class="required-note">Required - choose one answer.</span>
            </legend>

            <div class="radio-group">
              <label class="radio-option" for="notification-email">
                <input type="radio" id="notification-email" name="notification" value="Email" required>
                <span class="option-text">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input type="radio" id="notification-sms" name="notification" value="SMS" required>
                <span class="option-text">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input type="radio" id="notification-push" name="notification" value="Push Notifications" required>
                <span class="option-text">Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <p id="notification-status" class="status-message" aria-live="polite"></p>
        <p id="notification-error" class="error-message" aria-live="assertive"></p>

        <button type="submit">Submit preference</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const radios = Array.from(document.querySelectorAll('input[name="notification"]'));
    const statusMessage = document.querySelector("#notification-status");
    const errorMessage = document.querySelector("#notification-error");

    const setInvalidState = (isInvalid) => {
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    };

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedRadio = radios.find((radio) => radio.checked);

      if (!selectedRadio) {
        errorMessage.textContent = "Choose Email, SMS, or Push Notifications before submitting.";
        statusMessage.textContent = "";
        setInvalidState(true);
        radios[0].focus();
        return;
      }

      errorMessage.textContent = "";
      setInvalidState(false);
      statusMessage.textContent = `Preference saved: ${selectedRadio.value}.`;
    });

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        errorMessage.textContent = "";
        setInvalidState(false);
      });
    });
  </script>
</body>
